/*
 * A350232  Integers that are divisible by 4 and not by 5, and whose reverse
 *          is divisible by 5 and not by 4.
 * https://oeis.org/A350232
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   integers divisible by 4 and not by 5, whose reverse is divisible
 *            by 5 and not by 4, sorted in increasing order. The sequence is
 *            generated by * length 2: 52, 56 * length d≥3: numbers of the
 *            form 5·10^(d‑1) + M·100 + e where M has d‑3 decimal digits
 *            (0…10^(d‑3)–1) and e is one of {04,08,12,16,24,28...
 * Range:     u8 n <= 2, u16 n <= 51, u32 n <= 51, u64 n <= 51, u128 n <= 51,
 *            big any n
 * Helpers:   pow10
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include "../utils/pow10.h"  /* pow10(idx_t e) returns seq_t */

static const seq_t endings2[2] = { (seq_t)52, (seq_t)56 };

static const seq_t endings[20] = {
    (seq_t)4, (seq_t)8,  (seq_t)12, (seq_t)16,
    (seq_t)24, (seq_t)28, (seq_t)32, (seq_t)36,
    (seq_t)44, (seq_t)48, (seq_t)52, (seq_t)56,
    (seq_t)64, (seq_t)68, (seq_t)72, (seq_t)76,
    (seq_t)84, (seq_t)88, (seq_t)92, (seq_t)96
};

seq_t a(idx_t n) {
    /* convert to seq_t for comparison */
    seq_t nseq = (seq_t)n;

    /* handle the two 2‑digit terms */
    if (nseq <= (seq_t)2)
        return endings2[n - 1];

    /* cumulative count of terms processed */
    seq_t cumulative = (seq_t)2;
    size_t d = 3;
    seq_t count;
    /* find the digit length d that contains the nth term */
    for (;;) {
        /* number of middle digits = d-3 */
        seq_t pow_mid = pow10(d - 3);
        count = (seq_t)20 * pow_mid;
        cumulative += count;
        if (nseq <= cumulative)
            break;
        ++d;
    }

    /* offset within the block of length d (1‑based) */
    seq_t cum_before = cumulative - count;
    idx_t offset = (idx_t)(nseq - cum_before);  /* 1‑based */
    idx_t k = offset - 1;                       /* 0‑based */
    idx_t M = k / 20;                           /* middle block index */
    int e_index = (int)(k % 20);                /* index in endings array */

    seq_t base5 = pow10(d - 1);                 /* 10^(d‑1) */
    seq_t result = (seq_t)5 * base5
                 + (seq_t)M * (seq_t)100
                 + endings[e_index];
    return result;
}
